t.script:
document.addEventListener('DOMContentLoaded', function () {
  var P = window.SchoolPwa, SA = window.SchoolAttendance;
  var btn = document.getElementById('pn_toggle'), state = document.getElementById('pn_state');
  function refresh() {
    P.pushState().then(function (s) {
      if (s === 'unsupported') { state.textContent = "Non disponible sur ce navigateur (sur iPhone : installez d'abord l'application)."; btn.style.display = 'none'; }
      else { state.textContent = s === 'on' ? 'Activées' : 'Désactivées'; btn.textContent = s === 'on' ? 'Désactiver' : 'Activer'; btn.dataset.on = s === 'on' ? '1' : '0'; }
    });
  }
  btn.addEventListener('click', function () {
    (btn.dataset.on === '1' ? P.disablePush() : P.enablePush()).then(refresh, function (e) { state.textContent = e.message || String(e); });
  });
  document.querySelectorAll('.pn-pref').forEach(function (box) {
    box.addEventListener('change', function () { var p = {}; p[box.name] = box.checked; SA.rpcCall('/presence/notifications/preferences', p); });
  });
  refresh();
});
